export function solve({ data, chunkSize }) {
  if (chunkSize <= 0) return 'INVALID_SIZE';
  const result = [];
  for (let i = 0; i < data.length; i += chunkSize) {
    result.push(data.slice(i, i + chunkSize));
  }
  return result;
}

